// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }
    function testFuzz_property(address adr, bytes memory data, uint256 amount) public {
        amount = bound(amount, 0, address(this).balance / 2);
        vm.assume(adr != address(0));
        address helper = address(new Helper());
        vm.deal(address(c), 1 ether);
        vm.prank(c.Owner());
        c.Command{value: amount}(helper, data);
        bool ok = true;
        address helper2 = address(new Helper());
        vm.deal(address(c), 1 ether);
        vm.prank(c.Owner());
        try c.Command{value: amount}(helper2, data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract Helper {
    fallback() external payable {}
}
